-- van-der-merwe-gp-attorneys-florauna (owner)
UPDATE businesses SET description = 'Van Der Merwe GP Attorneys is a general legal practice based on Florauna Road in Florauna, Pretoria North, registered with the Law Society of South Africa at this address. The firm is classified as attorneys, notaries and conveyancers, giving it a broad scope covering general legal advice, notarial work and property conveyancing. South African Government Gazette records show the firm acting in deceased-estate matters, so estate-related legal work forms part of its practice alongside its broader general legal services. It serves individuals and businesses across Florauna and the surrounding Pretoria North area who need legal advice and representation, including notarial services, conveyancing and deceased-estate matters. Van Der Merwe GP Attorneys suits clients looking for a general legal practice covering attorney, notarial and conveyancing work, including deceased-estate matters, rather than a narrow specialist firm.', description_enriched_at = datetime('now') WHERE slug = 'van-der-merwe-gp-attorneys-florauna' AND description = 'Van Der Merwe GP Attorneys is a Florauna-based law firm that has acted as an executor and authorised agent in deceased estate matters.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
